const intro='https://spinningup.openai.com/en/latest/spinningup/rl_intro.html';
const gym='https://gymnasium.farama.org/';
export const rlConcepts=[
{id:21,title:'智能体与环境',en:'AGENT & ENVIRONMENT',chapter:5,desc:'采取动作，接收反馈，再做下一次选择。',tags:'rl 强化学习 agent environment 状态 动作 奖励 交互 mdp',intuition:'智能体通过动作影响环境。环境返回新的观察和奖励，下一次决策再基于新信息发生。',steps:['这是一个完全可观察的 4×4 网格：圆点是智能体，星号是终点。','选择动作，再点“执行动作”，实际获得 (s, a, r, s′)。','灰格不可通行，红格是陷阱；撞墙原地停留，也有每步代价。'],formula:'aₜ ~ π(·|sₜ);  环境 → (sₜ₊₁, rₜ, terminated)',controls:[['action','选择动作',['向上','向右','向下','向左'],'向上']],quiz:['环境反馈的奖励，等于“正确动作标签”吗？',['不等于，奖励评价动作带来的结果','等于，每步都会直接告诉最佳动作'],0,'奖励反馈结果，不一定提供最优动作。学习往往需要多次试错。'],note:'完全可观察、确定性教学网格；到达终点 +1，陷阱 −1，其余步 −0.04。观察一般不一定等于完整状态。',source:gym+'introduction/basic_usage/'},
{id:22,title:'奖励与折扣回报',en:'REWARD & RETURN',chapter:5,desc:'眼前的一分，和未来的一分有何不同？',tags:'rl 强化学习 reward return gamma discount 回报 折扣',intuition:'奖励是某一步的反馈，回报把一段未来奖励合在一起。折扣系数控制较远奖励的权重。',steps:['沿时间线依次得到奖励 [0, 0, 1, 2]。','改变 γ，查看每一步对当前回报的贡献。','这里是四步后终止的有限轨迹；γ=1 时就是直接求和。'],formula:'G₀ = r₀ + γr₁ + γ²r₂ + γ³r₃',controls:[['gamma','折扣系数 γ',0,1,.05,.9]],quiz:['奖励 [0, 0, 1]，γ=0.5，当前回报是多少？',['0.25','1'],0,'第三个奖励的权重为 γ²，所以回报为 0.5²×1=0.25。'],note:'回报中的时间下标采用 rₜ 为执行 aₜ 后得到的奖励；有限轨迹可取 γ=1。',source:intro+'#reward-and-return'},
{id:23,title:'策略',en:'POLICY',chapter:5,desc:'在同一个状态，你会怎样选择动作？',tags:'rl 强化学习 policy 策略 概率 随机',intuition:'策略描述在一个状态下如何选动作。它既可以直接选一个动作，也可以给每个动作分配概率。',steps:['这里比较“向左”和“向右”两个动作。','拖动右转偏好 θ，观察 softmax 给出的概率。','当前偏好只由你设置，本实验没有根据奖励训练策略。'],formula:'π(右|s)=exp(θ)/(1+exp(θ));  π(左|s)=1−π(右|s)',controls:[['theta','右转偏好 θ',-4,4,.1,1]],quiz:['随机策略是否表示每个动作概率都相同？',['是，总是各占一半','不是，可以有不同的选择概率'],1,'“随机”表示按概率选择；概率既可以均匀，也可以有明显偏好。'],source:intro+'#policies'},
{id:24,title:'状态价值与 Bellman',en:'VALUE & BELLMAN',chapter:5,desc:'一个位置的价值，来自之后能得到什么。',tags:'rl 强化学习 value bellman v q 状态价值 贝尔曼',intuition:'状态价值是在某个策略下，从这里出发的期望回报。Bellman 关系把它拆成眼前奖励和后续价值。',steps:['固定策略始终向右，经过三次动作进入终点。','只有最后一次动作获得 +1，其他动作奖励为 0。','改变 γ，看终点奖励如何影响更早的状态；终止后的价值为 0。'],formula:'Vπ(s)=Eπ[r+γVπ(s′)];  本例 V=[γ², γ, 1, 0]',controls:[['gamma','折扣系数 γ',0,1,.05,.9]],quiz:['终点只有进入时给 +1，终止后 V(terminal) 等于？',['0，不再获得未来奖励','1，每走一步继续 +1'],0,'+1 已记在进入终点的那次转移奖励中；终止后不再累计奖励。'],note:'展示的是固定向右策略的确定性有限轨迹，不是在求任意 MDP 的最优策略。',source:intro+'#value-functions'},
{id:25,title:'探索与利用',en:'EXPLORATION & EXPLOITATION',chapter:5,desc:'选已知最好的，还是试试没把握的？',tags:'rl 强化学习 epsilon greedy ε 探索 利用',intuition:'利用选择当前估计最好的动作；探索尝试其他可能。ε-greedy 以 ε 的概率均匀随机选动作，其余时间选贪心动作。',steps:['三个动作的当前估计固定为 [0.2, 0.5, 0.8]。','调节 ε，观察动作选择概率，而不是估计收益本身。','均匀探索也可能选中贪心动作，因此它的总概率大于 1−ε。'],formula:'π(a*)=1−ε+ε/3;  其他动作 π(a)=ε/3',controls:[['epsilon','探索概率 ε',0,1,.05,.2]],quiz:['三个动作、ε=0.3，唯一贪心动作被选概率是？',['0.7','0.8'],1,'利用概率 0.7，加上随机探索时也选到它的概率 0.3/3，总计 0.8。'],note:'假定当前最优动作唯一；Q 值只是估计值，探索不会保证每次得到更高奖励。',source:gym+'tutorials/training_agents/frozenlake_q_learning/'},
{id:26,title:'时序差分误差',en:'TEMPORAL-DIFFERENCE ERROR',chapter:5,desc:'用新的反馈，修正旧的价值估计。',tags:'rl 强化学习 td error 时序差分 bootstrap 终止 截断',intuition:'TD 误差比较旧估计与一步目标。目标由新奖励加上下一个状态的估计构成，因此称为自举。',steps:['当前 V(s)=1.2，下一状态 V(s′)=2。','改变奖励、γ 和是否真正终止，观察一步目标与误差。','真正终止时去掉后续价值；仅因时间上限截断时，通常仍需自举。'],formula:'δ = r + γ(1−terminated)V(s′) − V(s)',controls:[['reward','即时奖励 r',-1,2,.1,1],['gamma','折扣系数 γ',0,1,.05,.9],['terminal','真正终止',['否','是'],'否']],quiz:['真正终止时，一步 TD 目标是什么？',['r + γV(s′)','仅即时奖励 r'],1,'终止后没有后续回报，因此目标只保留这一步奖励。不要把所有截断都当成终止。'],note:'V 值由教学示例指定；这是单次 TD 目标计算，不代表价值已学习准确。',source:gym+'tutorials/gymnasium_basics/handling_time_limits/'},
{id:27,title:'Q-learning 小迷宫',en:'TABULAR Q-LEARNING',chapter:5,desc:'从随机试探，到自己找到一条路。',tags:'rl 强化学习 q-learning qlearning 迷宫 训练 策略 离线 off policy',intuition:'Q-learning 从转移数据更新状态动作价值。随着经验累积，智能体逐渐知道在某个格子里哪种动作更有价值。',steps:['点击训练，真实运行带 ε-greedy 探索的网格回合。','每一步按 Q-learning 公式更新表格，箭头显示当前贪心动作。','点击“评估策略”关闭探索，查看冻结 Q 表后的实际路线。'],formula:'Q(s,a)←Q(s,a)+α[r+γ(1−done)maxₐ′Q(s′,a′)−Q(s,a)]',controls:[['epsilon','探索概率 ε',0,1,.05,.25],['alpha','学习率 α',.05,1,.05,.3],['gamma','折扣系数 γ',0,.99,.01,.9]],quiz:['评估当前贪心策略时，是否应该继续更新 Q 表？',['不应该，应冻结参数再评估','应该，否则结果不准'],0,'训练用来改进参数；这里的评估关闭探索并冻结 Q 表，用固定策略走一回合。'],note:'表格算法在浏览器 CPU 运行，无神经网络。起点左下，终点右上；灰格为墙，红格为陷阱。每回合至多 80 步，评估上限 40 步；时间截断不屏蔽 TD 自举。',source:gym+'tutorials/training_agents/frozenlake_q_learning/'},
{id:28,title:'经验回放',en:'EXPERIENCE REPLAY',chapter:5,desc:'把走过的路存下来，打散后再学习。',tags:'rl 强化学习 replay buffer dqn off-policy 经验回放',intuition:'回放缓冲区保存交互得到的转移。训练时抽取一小批旧经验，能够重复利用数据，并减弱连续样本的时间相关性。',steps:['这里保存了网格里的 8 条合法转移，每条含状态、动作、奖励和下一状态。','点击重新采样，从缓冲区无放回抽取 3 条数据。','这些数据来自先前行为，不保证符合当前策略；是否可复用取决于具体算法。'],formula:'buffer ← (s,a,r,s′,terminated);  batch ~ sample(buffer)',controls:[['batch','采样批大小',1,5,1,3]],quiz:['经验回放是否让数据自动变成当前策略采集的？',['是，采样后就变成 on-policy','不会，它仍来自采集时的行为策略'],1,'重新采样不会改变数据来源。Q-learning/DQN 可利用此类离策略数据，但并非所有算法都能直接套用。'],note:'固定 8 条教学转移，无放回采样；这里只演示回放，不训练 DQN。',source:'https://spinningup.openai.com/en/latest/algorithms/ddpg.html#the-replay-buffer'}
];
